import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        long tmp = Long.parseLong(line[1]);
        if(n <= tmp) {
            pw.println(0);
            pw.flush();
            return;
        }
        int k = (int)tmp;
        long[] fact = new long[400001];
        long[] revFact = new long[400001];
        fact[0] = 1;
        for(int i=1;i<=400000;i++) {
            fact[i] = (fact[i-1] * i) % mod;
        }
        revFact[400000] = pow(fact[400000], mod - 2);
        for(int i=399999;i>=0;i--) {
            revFact[i] = (revFact[i+1] * (i+1)) % mod;
        }
        long totalComb = cmb(n, n - k, fact, revFact);
        long answer = 0;
        int sign = 1;
        for(int i=n - k; i>=1; i--) {
            long term = cmb(n - k, i, fact, revFact);
            long val = pow(i, n);
            answer = (answer + sign * term * val) % mod;
            sign *= -1;
        }
        answer = (answer * totalComb) % mod;
        if(k != 0) answer = (answer * 2) % mod;
        pw.println((answer + mod) % mod);
        pw.flush();
    }

    static final long mod = 998244353;

    static long cmb(int a, int b, long[] fact, long[] revFact) {
        if (a < b) return 0;
        return (((fact[a] * revFact[b]) % mod) * revFact[a - b]) % mod;
    }

    static long pow(long base, long exp) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
